import { createHash } from "node:crypto";
import { mkdir, writeFile } from "node:fs/promises";
import { createRequire } from "node:module";
import { fileURLToPath } from "node:url";
import path from "node:path";

// Use the encoder already installed with Next.js; generated files are committed.
const require = createRequire(import.meta.url);
const requireFromNext = createRequire(require.resolve("next/package.json"));
const sharp = requireFromNext("sharp");
const root = fileURLToPath(new URL("../", import.meta.url));
const output = path.join(root, "public/donetsk/images");
const sources = {
  vehicle: "mercedas-optimized.jpg",
  interior: "inside.jpg",
  pensioner: "pens.jpg",
  veteran: "svo.jpeg",
};
const images = {};

await mkdir(output, { recursive: true });

for (const [name, source] of Object.entries(sources)) {
  const input = path.join(root, "public", source);
  const { width, height } = await sharp(input).metadata();
  const widths = [...new Set([384, 640, width].filter((size) => size <= width))];
  const formats = {};

  for (const format of ["avif", "webp"]) {
    const variants = [];
    for (const size of widths) {
      const image = sharp(input).rotate().resize({ width: size, withoutEnlargement: true });
      const buffer = await (format === "avif"
        ? image.avif({ quality: 50, effort: 6 })
        : image.webp({ quality: 76, effort: 6 })).toBuffer();
      const hash = createHash("sha256").update(buffer).digest("hex").slice(0, 12);
      const filename = `${name}-${size}-${hash}.${format}`;
      await writeFile(path.join(output, filename), buffer);
      variants.push({ src: `/donetsk/images/${filename}`, width: size });
      console.log(`${filename}: ${buffer.length} bytes`);
    }
    formats[format] = variants;
  }

  images[name] = { width, height, ...formats };
}

await writeFile(
  path.join(root, "app/donetsk/images.generated.ts"),
  `// Generated by scripts/optimize-donetsk-images.mjs. Do not edit by hand.\nexport const donetskImages = ${JSON.stringify(images, null, 2)} as const;\n`,
);
